descriptor.controllerScript:
self.onInit = function() {
    // No initialization steps needed for a basic HTML wrapper
};

self.onDataUpdated = function() {
    var tbData = self.ctx.data; 
    
    // Safely look up elements inside this specific widget container
    var container = self.ctx.$container[0];
    var maxEl = container.querySelector('#max-delta');
    var minEl = container.querySelector('#min-delta');
    var p95El = container.querySelector('#p95-delta');

    if (!maxEl || !minEl || !p95El) return;

    // Check if both data keys are present in the widget configuration
    if (!tbData || tbData.length < 2) {
        maxEl.innerText = "Error: Add 2 data keys";
        minEl.innerText = "--";
        p95El.innerText = "--";
        return;
    }

    var dataA = tbData[0].data; 
    var dataB = tbData[1].data; 

    // Check if the history array actually contains values
    if (!dataA || !dataB || dataA.length === 0 || dataB.length === 0) {
        maxEl.innerText = "No history data";
        minEl.innerText = "Check time window";
        p95El.innerText = "Waiting...";
        return;
    }

    var deltas = [];
    var len = Math.min(dataA.length, dataB.length);

    // Calculate absolute delta differences point-by-point
    for (var i = 0; i < len; i++) {
        var valA = dataA[i][1];
        var valB = dataB[i][1];
        deltas.push(Math.abs(valA - valB));
    }

    if (deltas.length > 0) {
        var maxDelta = Math.max.apply(null, deltas).toFixed(1);
        var minDelta = Math.min.apply(null, deltas).toFixed(1);
        
        // Sort ascending to extract the 95th percentile
        deltas.sort(function(a, b) { return a - b; });
        var percentileIndex = Math.floor(0.95 * deltas.length);
        var p95Delta = deltas[percentileIndex].toFixed(1);

        // Update the HTML
        maxEl.innerHTML = maxDelta + " °C";
        minEl.innerHTML = minDelta + " °C";
        p95El.innerHTML = p95Delta + " °C";
    }
};

self.typeParameters = function() {
    return {
        maxDataKeys: 2 // Limits the user to selecting exactly your 2 temperature streams
    };
};

